  RS.begin(BAUD);

  gameStrip.begin();
  borderStrip.begin();
  applyBrightness(runtimeBrightness);
  clearAll();
  initPlayerColors();
  refreshRuntimePalette(false);
  applyPlayerState(runtimePlayerState);
  applyBorderState(runtimeBorderState);

  Serial.println(F("MEGA RS485 PitterOmat ready."));
}

void loop() {
  rs485Poll();
  updateJokerAnimation();
  updateHitBlink();
  delay(2);
}
