    auto fillRange = [&](uint8_t start, uint8_t end, uint32_t col) {
      if (start <= end) {
        for (uint8_t g = start; g <= end; ++g) {
          uint16_t base = groupBase(g);
          for (uint8_t i = 0; i < 12; ++i) gameStrip.setPixelColor(base + i, col);
